//! Ghost posts, on any site running Ghost. A page hook: when a fetched page is generated by
//! Ghost and carries its site's public Content API key (`data-key` and `data-api` on the
//! portal or search script, which Ghost documents as safe to expose), its card takes the post's
//! title, excerpt, feature image, dates, authors and tags from
//! `{api}posts/slug/{slug}/?key=…`. The API must be on the page's own origin. Links are read by
//! the web route, never claimed by their shape.
use super::{list, text, web_url, Context, Example, Source};
use crate::{
    model::ResourceMeta,
    resolver::egress::{FetchOptions, Fetched},
};
use anyhow::{Context as _, Result};
use async_trait::async_trait;
use serde_json::Value;
use url::Url;

pub struct Ghost;

fn key(value: &str) -> bool {
    (20..=64).contains(&value.len()) && value.bytes().all(|b| b.is_ascii_hexdigit())
}
fn slug(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 191
        && value
            .bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-')
}

/// What a Ghost page says about itself: its Content API, the public key and the post's slug.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Site {
    pub api: Url,
    pub key: String,
    pub slug: String,
}

impl Site {
    /// Whether the page's text holds what a Ghost page names its site with: without it the
    /// markup names none, and is not parsed.
    fn marked(page: &Fetched) -> bool {
        let body = String::from_utf8_lossy(&page.body);
        body.contains("data-key") && body.contains("content=\"Ghost")
    }
    pub fn of_page(page: &Fetched) -> Option<Self> {
        if !Self::marked(page) {
            return None;
        }
        let body = String::from_utf8_lossy(&page.body);
        let html = crate::resolver::html::document(&body).ok()?;
        let generator = scraper::Selector::parse("head meta[name='generator']").ok()?;
        let ghost = html
            .select(&generator)
            .filter_map(|m| m.value().attr("content"))
            .any(|c| c.starts_with("Ghost "));
        if !ghost {
            return None;
        }
        let scripts = scraper::Selector::parse("head script[data-key][data-api]").ok()?;
        let (api, key) = html.select(&scripts).find_map(|s| {
            let el = s.value();
            let api = page.url.join(el.attr("data-api")?).ok()?;
            let key = el.attr("data-key")?;
            (api.origin() == page.url.origin()
                && api.path().ends_with("/ghost/api/content/")
                && api.query().is_none()
                && self::key(key))
            .then(|| (api, key.to_owned()))
        })?;
        let slug = page
            .url
            .path_segments()?
            .rfind(|s| !s.is_empty())?
            .to_owned();
        self::slug(&slug).then_some(Self { api, key, slug })
    }
    /// The post by its slug, with its authors and tags and only the fields a card needs.
    pub fn post_url(&self) -> String {
        let mut url = self
            .api
            .join(&format!("posts/slug/{}/", self.slug))
            .expect("a slug joins");
        url.query_pairs_mut()
            .append_pair("key", &self.key)
            .append_pair("include", "authors,tags")
            .append_pair(
                "fields",
                "id,uuid,title,url,custom_excerpt,excerpt,feature_image,published_at,updated_at",
            );
        url.into()
    }
}

/// The page's card with the post, or `None` when the post is not this page.
pub fn card(doc: &ResourceMeta, page: &Url, body: &[u8]) -> Result<Option<ResourceMeta>> {
    let v: Value = serde_json::from_slice(body).context("Ghost answered no JSON")?;
    let post = &v["posts"][0];
    let Some(url) = text(&post["url"]) else {
        return Ok(None);
    };
    let same = matches!(
        (crate::model::identity(&url), crate::model::identity(page.as_str())),
        (Ok(a), Ok(b)) if a.1 == b.1
    );
    let Some(title) = text(&post["title"]).filter(|_| same) else {
        return Ok(None);
    };
    let mut doc = doc.clone();
    doc.name = Some(title);
    if let Some(excerpt) = text(&post["custom_excerpt"]).or_else(|| text(&post["excerpt"])) {
        let excerpt = excerpt.split_whitespace().collect::<Vec<_>>().join(" ");
        doc.description = Some(excerpt.chars().take(300).collect());
    }
    if let Some(image) = text(&post["feature_image"]).filter(|u| web_url(u).is_some()) {
        doc.image = Some(image);
    }
    if !doc.type_path.iter().any(|t| t == "Article") {
        doc.set_type("BlogPosting");
    }
    doc.source = "ghost".into();
    let names = |key: &str| -> Vec<String> {
        post[key]
            .as_array()
            .into_iter()
            .flatten()
            // Internal tags (`#name`) are the site's own bookkeeping.
            .filter(|t| t["visibility"] != "internal")
            .filter_map(|t| text(&t["name"]))
            .filter(|n| !n.starts_with('#'))
            .collect()
    };
    for (key, value) in [
        ("published", text(&post["published_at"])),
        ("modified", text(&post["updated_at"])),
        ("author", list(&names("authors"))),
        ("tags", list(&names("tags"))),
        ("uuid", text(&post["uuid"])),
    ] {
        if let Some(value) = value {
            doc.attributes.insert(key.into(), value);
        }
    }
    Ok(Some(doc))
}

#[async_trait]
impl Source for Ghost {
    fn name(&self) -> &'static str {
        "ghost"
    }
    fn e2e(&self) -> Option<super::E2e> {
        use super::{E2e, E2eAnswer, E2eSample};
        Some(E2e {
            samples: &[
                E2eSample {
                    kind: "ghost",
                    uri: "https://www.privacyguides.org/news/2026/10/19/leaked-document-suggests-cellebrite-can-wirelessly-exploit-iphones/",
                    card_type: "Article",
                    group_with: None,
                },
            ],
            answers: &[
                E2eAnswer {
                    host: "www.privacyguides.org",
                    path: "/ghost/api/content/posts/slug/leaked-document-suggests-cellebrite-can-wirelessly-exploit-iphones/",
                    query: &[],
                    header: None,
                    content_type: "application/json",
                    file: "post-cellebrite.json",
                },
                E2eAnswer {
                    host: "www.privacyguides.org",
                    path: "/news/2026/10/19/leaked-document-suggests-cellebrite-can-wirelessly-exploit-iphones/",
                    query: &[],
                    header: None,
                    content_type: "text/html; charset=utf-8",
                    file: "page-cellebrite.html",
                },
            ],
        })
    }
    fn reads(&self, _uri: &str) -> bool {
        false
    }
    fn hooks_pages(&self) -> bool {
        true
    }
    fn facts(&self) -> &'static [&'static str] {
        &["published", "modified", "author", "tags", "uuid"]
    }
    fn examples(&self) -> &'static [Example] {
        &[Example {
            uri: "https://www.privacyguides.org/news/2026/10/19/leaked-document-suggests-cellebrite-can-wirelessly-exploit-iphones/",
            card_type: "Article",
        }]
    }
    async fn resolve(&self, _cx: &Context<'_>, _uri: &str) -> Result<ResourceMeta> {
        anyhow::bail!("Ghost pages are read by the web route")
    }
    async fn page(
        &self,
        cx: &Context<'_>,
        _uri: &str,
        page: &Fetched,
        doc: &ResourceMeta,
    ) -> Result<Option<ResourceMeta>> {
        // The cheap test first: only a page with the markers in its text is copied and waits
        // for a parse.
        if !Site::marked(page) {
            return Ok(None);
        }
        let found = page.clone();
        let Some(site) = crate::resolver::html::blocking(move || Site::of_page(&found)).await?
        else {
            return Ok(None);
        };
        let f = cx
            .fetch(
                &site.post_url(),
                &FetchOptions {
                    accept: Some("application/json".into()),
                    // The key is public, but stays out of stored addresses and logs all the same.
                    sensitive: true,
                    ..Default::default()
                },
            )
            .await?;
        if f.status != 200 {
            return Ok(None);
        }
        card(doc, &page.url, &f.body)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::sources::fixture;

    const PAGE: &str = "https://www.privacyguides.org/news/2026/10/19/leaked-document-suggests-cellebrite-can-wirelessly-exploit-iphones/";
    const POST: &str = "https://www.privacyguides.org/ghost/api/content/posts/slug/leaked-document-suggests-cellebrite-can-wirelessly-exploit-iphones/?key=77a3997ec1bec1a6203fcb4166&include=authors%2Ctags&fields=id%2Cuuid%2Ctitle%2Curl%2Ccustom_excerpt%2Cexcerpt%2Cfeature_image%2Cpublished_at%2Cupdated_at";
    fn read(file: &str) -> Vec<u8> {
        fixture::read("ghost", file)
    }
    fn page() -> Fetched {
        fixture::page(
            PAGE,
            "text/html; charset=utf-8",
            read("page-cellebrite.html"),
            None,
        )
    }
    fn web_card() -> ResourceMeta {
        let mut doc = ResourceMeta::new(PAGE, "opengraph", 3600);
        doc.set_type("Article");
        doc
    }

    #[test]
    fn the_page_names_its_api_and_key() {
        let site = Site::of_page(&page()).unwrap();
        assert_eq!(
            site.api.as_str(),
            "https://www.privacyguides.org/ghost/api/content/"
        );
        assert_eq!(site.key, "77a3997ec1bec1a6203fcb4166");
        assert_eq!(
            site.slug,
            "leaked-document-suggests-cellebrite-can-wirelessly-exploit-iphones"
        );
        assert_eq!(site.post_url(), POST);
        let html = |head: &str| {
            fixture::page(
                "https://g.example/a-post/",
                "text/html",
                format!("<html><head>{head}</head></html>").into_bytes(),
                None,
            )
        };
        let ghost = r#"<meta name="generator" content="Ghost 6.68">"#;
        let script = |api: &str, key: &str| {
            format!(r#"<script data-key="{key}" data-api="{api}"></script>"#)
        };
        assert!(Site::of_page(&html(&format!(
            "{ghost}{}",
            script(
                "https://g.example/ghost/api/content/",
                "0123456789abcdef0123456789"
            )
        )))
        .is_some());
        // Markers in the body are the page's text, not its head.
        let body = fixture::page(
            "https://g.example/a-post/",
            "text/html",
            format!(
                "<html><head></head><body>{ghost}{}</body></html>",
                script(
                    "https://g.example/ghost/api/content/",
                    "0123456789abcdef0123456789"
                )
            )
            .into_bytes(),
            None,
        );
        assert_eq!(Site::of_page(&body), None);
        for head in [
            // Not Ghost.
            script(
                "https://g.example/ghost/api/content/",
                "0123456789abcdef0123456789",
            ),
            // The API on another origin, another path, or a key that is not one.
            format!(
                "{ghost}{}",
                script(
                    "https://g.ghost.io/ghost/api/content/",
                    "0123456789abcdef0123456789"
                )
            ),
            format!(
                "{ghost}{}",
                script("https://g.example/elsewhere/", "0123456789abcdef0123456789")
            ),
            format!(
                "{ghost}{}",
                script("https://g.example/ghost/api/content/", "not-a-key")
            ),
        ] {
            assert_eq!(Site::of_page(&html(&head)), None, "{head}");
        }
    }

    #[test]
    fn the_post_makes_the_card() {
        let url = Url::parse(PAGE).unwrap();
        let doc = card(&web_card(), &url, &read("post-cellebrite.json"))
            .unwrap()
            .unwrap();
        assert_eq!(
            doc.name.as_deref(),
            Some("Leaked Document Suggests Cellebrite Can Wirelessly Exploit iPhones")
        );
        assert_eq!(doc.type_name, "Article");
        assert_eq!(doc.source, "ghost");
        assert_eq!(doc.attributes["author"], "Fria Reyes");
        assert_eq!(doc.attributes["tags"], "News Briefs");
        assert_eq!(
            doc.attributes["uuid"],
            "d2964f7e-f369-4671-8d5c-c64a9b22747a"
        );
        assert_eq!(doc.attributes["published"], "2026-10-19T12:13:00.000-05:00");
        assert!(doc
            .image
            .unwrap()
            .starts_with("https://images.unsplash.com/"));
        let other = Url::parse("https://www.privacyguides.org/news/other/").unwrap();
        assert!(card(&web_card(), &other, &read("post-cellebrite.json"))
            .unwrap()
            .is_none());
    }

    #[tokio::test(start_paused = true)]
    async fn the_hook_fetches_the_post_once() {
        let (egress, recorded) = fixture::egress(vec![(
            POST,
            200,
            "application/json",
            read("post-cellebrite.json"),
        )]);
        let cx = Context {
            egress: &egress,
            ttl: 3600,
        };
        let doc = Ghost
            .page(&cx, PAGE, &page(), &web_card())
            .await
            .unwrap()
            .unwrap();
        assert_eq!(doc.attributes["author"], "Fria Reyes");
        assert_eq!(recorded.asked(), [POST]);
        // Through the web route's hooks, and not when Ghost is switched off.
        let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(10);
        let doc =
            crate::sources::page_hooks_with(&egress, PAGE, &page(), web_card(), deadline, None)
                .await;
        assert_eq!(doc.source, "ghost");
        let mut off = crate::sources::SourcesConfig::default();
        off.0.insert(
            "ghost".into(),
            crate::sources::Switch {
                enabled: false,
                ..Default::default()
            },
        );
        let doc = crate::sources::page_hooks_with(
            &egress,
            PAGE,
            &page(),
            web_card(),
            deadline,
            Some(&off),
        )
        .await;
        assert_eq!(doc.source, "opengraph");
    }
}
